namespace TessitoreGM.Gm;

internal static class DashboardStyles
{
    public const string Content = @"
:root{color-scheme:dark;--ink:#f4efe3;--muted:#aaa393;--panel:rgba(31,35,32,.84);--line:rgba(226,210,176,.16);--gold:#d9b46f}
*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--ink);background:radial-gradient(circle at 85% 5%,rgba(143,174,145,.14),transparent 32rem),radial-gradient(circle at 8% 30%,rgba(217,180,111,.1),transparent 28rem),#111512;font-family:Inter,ui-sans-serif,system-ui,sans-serif}
.shell{width:min(1160px,calc(100% - 32px));margin:auto;padding:48px 0 32px}.hero{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:32px}.eyebrow{margin:0 0 8px;color:var(--gold);font-size:.72rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}
.login-shell{min-height:calc(100vh - 80px);display:grid;place-items:center}.login-card{width:min(100%,460px);margin:0;padding:30px;border:1px solid var(--line);border-radius:20px;background:var(--panel);box-shadow:0 24px 90px rgba(0,0,0,.32)}.login-card h1{font-size:clamp(2.5rem,10vw,4.5rem)}.login-card>p{color:var(--muted);line-height:1.55}.login-card form{display:grid;gap:10px;margin-top:24px}.login-card label{color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}.login-card input{border:1px solid var(--line);border-radius:12px;padding:14px;color:var(--ink);background:#1b201c;font:inherit;font-size:1.25rem;letter-spacing:.16em;text-align:center}.login-error{padding:10px 12px;border-radius:10px;color:#ffd0c7!important;background:rgba(180,55,40,.18)}.login-switch{display:block;margin-top:22px;color:var(--gold);font-size:.84rem;text-align:center}.access-code-page{align-items:center;text-align:center}.access-code-page>p{max-width:38rem}.access-code{display:block;margin:10px 0 28px;color:var(--gold);font:700 clamp(2.8rem,12vw,5.5rem) ui-monospace,monospace;letter-spacing:.12em}
h1,h2,h3,p{margin-top:0}h1,h2,h3{font-family:Georgia,serif;font-weight:500}h1{margin-bottom:10px;font-size:clamp(2.5rem,7vw,5.5rem);line-height:.95;letter-spacing:-.04em}h2{margin-bottom:0;font-size:2rem}h3{margin-bottom:0;font-size:1.55rem}.lede,.empty-state>p{color:var(--muted);max-width:46rem;line-height:1.6}
button,.button{display:inline-block;border:1px solid var(--gold);border-radius:999px;padding:12px 20px;color:#15130d;background:var(--gold);font:inherit;font-weight:800;text-decoration:none;cursor:pointer}.secondary{color:var(--gold);background:transparent}.hero-actions{display:flex;gap:10px;align-items:center}
.campaign-control{display:flex;justify-content:space-between;align-items:end;gap:24px;padding:24px;border:1px solid var(--line);border-radius:18px;background:rgba(143,174,145,.07)}.campaign-control p{margin-bottom:0;color:var(--muted)}.campaign-forms{display:grid;grid-template-columns:1fr 1fr;gap:12px;min-width:min(100%,520px)}.campaign-forms form{display:grid;gap:8px}.campaign-control label{color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}.campaign-control select,.campaign-control input{min-width:0;border:1px solid var(--line);border-radius:10px;padding:11px 14px;color:var(--ink);background:#1b201c;font:inherit}
.scene-focus{display:flex;justify-content:space-between;align-items:end;gap:24px;padding:24px;border:1px solid rgba(217,180,111,.38);border-radius:18px;background:linear-gradient(120deg,rgba(217,180,111,.09),rgba(143,174,145,.06))}.scene-focus p{margin-bottom:0;color:var(--muted);line-height:1.5}.scene-focus strong{color:var(--ink)}.scene-focus form{display:grid;grid-template-columns:minmax(190px,1fr) auto;gap:8px;align-items:end;min-width:min(100%,440px)}.scene-focus label{grid-column:1/-1;color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}.scene-focus select{min-width:0;border:1px solid var(--line);border-radius:10px;padding:11px 14px;color:var(--ink);background:#1b201c;font:inherit}
.scene-cast{padding:24px;border:1px solid var(--line);border-radius:18px;background:var(--panel)}.scene-cast-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.scene-cast form,.scene-cast-empty{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:18px;border-radius:14px;background:rgba(255,255,255,.035)}.scene-cast h3{grid-column:1/-1;font-size:1.3rem}.scene-cast label{color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}.scene-cast select{min-width:0;border:1px solid var(--line);border-radius:10px;padding:10px 12px;color:var(--ink);background:#1b201c;font:inherit}.scene-cast button{grid-column:1/-1}.scene-cast-empty{display:block}.scene-cast-empty p{margin:8px 0 0;color:var(--muted)}
.time-control{display:flex;justify-content:space-between;align-items:end;gap:24px;padding:24px;border:1px solid var(--line);border-radius:18px;background:var(--panel)}.time-control p{margin-bottom:0;color:var(--muted)}.time-control form{display:grid;grid-template-columns:auto auto;gap:8px;align-items:center}.time-control label{color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}.time-control select{min-width:150px;border:1px solid var(--line);border-radius:10px;padding:11px 14px;color:var(--ink);background:#1b201c;font:inherit}.time-control button{grid-column:1/-1}
.consequence-preview{padding:26px;border:1px solid var(--gold);border-radius:18px;background:rgba(217,180,111,.08)}.consequence-preview p{color:var(--muted);line-height:1.55}.consequence-preview ol{margin:22px 0;padding:0;list-style:none;border-top:1px solid var(--line)}.consequence-preview li{display:grid;grid-template-columns:120px 1fr;gap:18px;padding:13px 2px;border-bottom:1px solid var(--line)}.consequence-preview time{color:var(--gold);font:.82rem ui-monospace,monospace}.preview-actions{display:flex;gap:10px;justify-content:flex-end}.preview-actions form{margin:0}
.world-action{display:flex;justify-content:space-between;align-items:end;gap:24px;padding:24px;border:1px solid var(--line);border-radius:18px;background:rgba(217,180,111,.055)}.world-action p{margin-bottom:0;color:var(--muted)}.world-action form{display:grid;grid-template-columns:auto minmax(150px,1fr);gap:8px;align-items:center}.world-action label{color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}.world-action select,.world-action input,.world-action textarea{border:1px solid var(--line);border-radius:10px;padding:11px 14px;color:var(--ink);background:#1b201c;font:inherit}.world-action textarea{resize:vertical}.world-action button{grid-column:1/-1}.player-action form{min-width:min(100%,520px)}
.world-strip{display:grid;grid-template-columns:1.4fr repeat(3,1fr);border:1px solid var(--line);border-radius:18px;overflow:hidden;background:rgba(255,255,255,.025)}.world-strip article{padding:20px;border-right:1px solid var(--line)}.world-strip article:last-child{border-right:0}.world-strip span,.stats span,footer span{display:block;margin-bottom:7px;color:var(--muted);font-size:.72rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.world-strip strong{font-family:Georgia,serif;font-size:1.35rem;font-weight:500}
section{margin-top:52px}.section-heading{margin-bottom:18px}.npc-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.npc-card{padding:22px;border:1px solid var(--line);border-radius:18px;background:var(--panel);box-shadow:0 18px 70px rgba(0,0,0,.18)}.player-card{border-color:rgba(217,180,111,.42)}.npc-top{display:flex;justify-content:space-between;align-items:start;gap:12px;padding-bottom:22px;border-bottom:1px solid var(--line)}.role{margin-bottom:5px;color:var(--muted);font-size:.78rem;text-transform:capitalize}.location{flex:none;max-width:45%;border-radius:999px;padding:7px 10px;color:#cde0ce;background:rgba(143,174,145,.12);font-size:.75rem;text-align:center}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:20px 0}.stats div{padding:12px;border-radius:12px;background:rgba(255,255,255,.035)}.knowledge span{color:var(--gold);font-size:.72rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.knowledge p{margin:6px 0 0;color:var(--muted);font-size:.86rem;line-height:1.5}
.player-access-form{margin-top:18px}.player-access-form button{width:100%;padding:9px 12px}.player-view-link{display:block;margin-top:12px;padding-top:15px;border-top:1px solid var(--line);color:var(--gold);font-size:.82rem;font-weight:800;text-decoration:none}.player-hero{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:30px}.player-live-controls{display:grid;gap:10px;justify-items:end}.live-status{color:#bcd7bd;font-size:.76rem;font-weight:700}.live-status i{display:inline-block;width:8px;height:8px;margin-right:7px;border-radius:50%;background:#7fc884;box-shadow:0 0 0 4px rgba(127,200,132,.12)}.player-update{position:fixed;right:18px;bottom:18px;z-index:20;width:min(420px,calc(100% - 36px));padding:18px;border:1px solid var(--gold);border-radius:16px;background:#20251f;box-shadow:0 18px 70px rgba(0,0,0,.45)}.player-update[hidden]{display:none}.player-update p{margin:0 0 12px;color:var(--muted);line-height:1.45}.player-update strong{color:var(--ink)}.player-update button{width:100%;padding:9px 14px}.player-view section{margin-top:38px}.player-summary{grid-template-columns:1.4fr 1fr 1fr 1.4fr}.player-panel{padding:22px;border:1px solid var(--line);border-radius:18px;background:var(--panel)}.player-panel p{margin:0;color:var(--muted);line-height:1.55}.player-panel ul{display:grid;gap:10px;margin:0;padding:0;list-style:none}.player-panel li{padding:12px 14px;border-radius:12px;background:rgba(255,255,255,.035)}.player-resource-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.player-resource-grid>div{padding:15px;border-radius:12px;background:rgba(255,255,255,.035)}.player-resource-grid span{display:block;margin-bottom:6px;color:var(--muted);font-size:.72rem;font-weight:700;text-transform:uppercase}
.player-action-box{padding:24px;border:1px solid var(--gold);border-radius:18px;background:rgba(217,180,111,.07)}.player-action-box form{display:grid;gap:10px}.player-action-box label,.gm-action-item label{color:var(--muted);font-size:.76rem;font-weight:700}.player-action-box textarea,.gm-action-item textarea,.gm-action-item select,.gm-action-item input{width:100%;margin-top:6px;border:1px solid var(--line);border-radius:10px;padding:11px 13px;color:var(--ink);background:#1b201c;font:inherit}.player-action-list,.gm-action-list{display:grid;gap:12px}.player-action-item,.gm-action-item{padding:20px;border:1px solid var(--line);border-radius:16px;background:var(--panel)}.player-action-item p,.gm-action-item p{margin:7px 0 0;line-height:1.5}.action-status{color:var(--gold);font-size:.72rem;font-weight:800;letter-spacing:.07em;text-transform:uppercase}.action-resolution,.roll-summary{margin-top:14px;padding:12px;border-radius:10px;background:rgba(255,255,255,.04)}.action-resolution strong{color:var(--gold);font-size:.78rem}.player-action-item form{margin-top:14px}.empty-copy{margin:0;padding:20px;border:1px solid var(--line);border-radius:16px;color:var(--muted);background:var(--panel)}.gm-action-item{display:grid;grid-template-columns:minmax(220px,1.2fr) minmax(230px,1fr) minmax(230px,1fr);gap:16px}.roll-request-form,.action-resolution-form{display:grid;gap:8px}.checkbox-label{display:flex;align-items:center;gap:8px}.checkbox-label input{width:auto;margin:0}.resolution-buttons{display:flex;gap:8px}.resolution-buttons button{flex:1;padding:9px 12px}
.chronicle ol{margin:0;padding:0;list-style:none;border-top:1px solid var(--line)}.chronicle li{display:grid;grid-template-columns:120px 1fr;gap:18px;padding:16px 4px;border-bottom:1px solid var(--line)}.chronicle time{color:var(--gold);font:.82rem ui-monospace,monospace}.chronicle p{margin:0;line-height:1.45}.chronicle-full li{grid-template-columns:170px 1fr}.chronicle-summary{grid-template-columns:2fr 1fr 1fr}footer{display:flex;justify-content:space-between;gap:20px;margin-top:52px;padding-top:18px;border-top:1px solid var(--line);color:var(--muted);font-size:.76rem}code,pre{overflow-wrap:anywhere;color:#d6dfd5;font-family:ui-monospace,monospace}.empty-state{min-height:75vh;display:flex;flex-direction:column;align-items:flex-start;justify-content:center}.empty-state pre{max-width:100%;padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--panel);white-space:pre-wrap}
@media(max-width:800px){.shell{width:min(100% - 22px,640px);padding-top:28px}.hero{align-items:start}h1{font-size:3.35rem}.world-strip{grid-template-columns:1fr 1fr}.world-strip article:first-child{grid-column:1/-1;border-bottom:1px solid var(--line)}.npc-grid,.scene-cast-grid{grid-template-columns:1fr}.campaign-control,.scene-focus,.time-control,.world-action{display:block}.campaign-forms,.scene-focus form,.time-control form,.world-action form{margin-top:20px}.player-resource-grid{grid-template-columns:1fr 1fr}.gm-action-item{grid-template-columns:1fr}section{margin-top:40px}}
@media(max-width:480px){.hero,.player-hero{display:block}.player-live-controls{margin-top:14px;justify-items:stretch}.player-live-controls button{width:100%;margin-top:0}.live-status{text-align:center}.hero-actions{display:grid;margin-top:12px}.hero-actions button,.hero-actions .button{width:100%;margin:0;text-align:center}.campaign-forms,.scene-focus form,.scene-cast form{grid-template-columns:1fr}.scene-focus label,.scene-cast h3,.scene-cast button{grid-column:auto}.time-control form,.world-action form{grid-template-columns:1fr}.time-control button,.world-action button{grid-column:auto}.consequence-preview li,.chronicle li{grid-template-columns:1fr;gap:6px}.preview-actions{display:grid}.preview-actions button{width:100%}.player-resource-grid{grid-template-columns:1fr}footer{display:block}}
@media print{body{color:#171913;background:#fff}.shell{width:100%;padding:0}.hero-actions,footer{display:none}.world-strip,.chronicle li{border-color:#ccc}.world-strip{background:#fff}.chronicle time,.eyebrow{color:#6b5428}}";
}
